#include <random>
#include <sstream>
#include <cassert>
#include <iostream>

int main() {
    using Distribution = std::piecewise_constant_distribution<double>;
    std::mt19937 engine{42};
    Distribution distribution({0.0, 1.0, 2.0}, [](double) { return 1.0; });
    auto parameters = distribution.param();
    Distribution copy(parameters);
    assert(copy == distribution);
    assert(copy.intervals() == distribution.intervals());
    assert(copy.densities() == distribution.densities());
    auto value = distribution(engine);
    assert(value >= distribution.min() && value <= distribution.max());
    // Replace the parameters, then discard any cached random values.
    distribution.param(parameters);
    distribution.reset();
    // Save and restore the complete distribution state.
    std::stringstream saved;
    saved << distribution;
    saved >> copy;
    assert(copy == distribution);
    std::cout << "Checks passed\n";
}
